// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.bns.BnsPanelToGroupBox(panel_Top);
        $c.bns.BnsPanelToGroupBox(panel_1);

        // 상장일자 기본 세팅, 오늘+1일
        scwin.setSearchDt();

        // 예탁원발행등록사실정보 api 최근 호출일 조회
        scwin.getKsdApiCallDt();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS24600.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS24600.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List1_OnRowPosChanged
 * @description List1 On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_List1_OnRowPosChanged = function(row) {
    try {
        if (dts_List1.getRowCount() < 1) return;
        scwin.search1();
        scwin.search2();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS24600.dts_List1_OnRowPosChanged" });
    }
};

/**
 * @method
