/**
 * @method
 * @name btn_ISU_CD_SEARCH_onclick
 * @description btn_ISU_CD_SEARCH 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISU_CD_SEARCH_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParListBndIsu;
        scwin.fn_SetPar = scwin.setParListBndIsu;
        $c.bns.fn_PopListBndIsuSearch(btn_ISU_CD_SEARCH);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS24600.btn_ISU_CD_SEARCH_onclick" });
    }
};

/**
 * @method
 * @name txb_StdCd_onkeypress
 * @description txb_StdCd onkeypress 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_StdCd_onkeypress = function() {
    try {
        if (window.event.keyCode === 13 && txb_StdCd.getValue() !== "") {
            scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS24600.txb_StdCd_onkeypress" });
    }
};

