/**
 * @method
 * @name grd_List1_OnDblClick
 * @description grd_List1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List1_OnDblClick = function(row, colid) {
    try {
        const payCertYn = dts_List1.getCellData(dts_List1.getRowPosition(), "PAY_CERT_YN");
        if (colid === "PAY_CERT_YN") {
            scwin.fn_GetPar = scwin.getCommonKey;
            $c.bns.fn_PopAttachDocSearch(grd_List1);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS24600.grd_List1_OnDblClick" });
    }
};

