///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description 발행등록사실확인 목록 조회
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    if (!$c.stf.compareFromToDate2(edt_FromDt, edt_ToDt)) {
        return;
    }
    dts_List1.removeAll();
    let param = '';
    param += "&{P}V_STD_CD=" + txb_StdCd.getValue(); // 표준코드
    param += "&{P}V_ISU_NM=" + txb_IsuNm.getValue(); // 종목명
    param += "&{P}V_FROM_DT=" + edt_FromDt.getValue(); // From Date
    param += "&{P}V_TO_DT=" + edt_ToDt.getValue(); // To Date

    let dsNm = 'BNS_ISU_REG_FACT_CONFRM_LIST';
    let qryId = 'lds.stf.bnsdecl_mgr.select.selectIsuRegFactConfrmList';
    $c.bns.fn_SearchBns("ULDBNS24600.xml", dts_List1, dsNm, qryId, param);
};

/**
 * @method
 * @name search1
 * @description 예탁원 발행등록내역 조회
 * @returns {void}
 * @hidden N
 */
scwin.search1 = function() {
    dts_List2.removeAll();
    const std_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "STD_CD");
    const ksd_reg_dd = dts_List1.getCellData(dts_List1.getRowPosition(), "KSD_REG_DD"); // 등록일자

    let param = '';
    param += "&{P}V_STD_CD=" + std_cd; // 표준코드
    param += "&{P}V_FROM_DT=" + ksd_reg_dd; // 행사일자
    param += "&{P}V_TO_DT=" + ksd_reg_dd; // 행사일자

    let dsNm = 'BNS_KSD_RER_FACT_RCV_LIST';
    let qryId = 'lds.stf.bnsdecl_mgr.select.selectKsdRegFactRcvList';
    $c.bns.fn_SearchBns("ULDBNS24600.xml", dts_List2, dsNm, qryId, param);
};

/**
 * @method
 * @name search2
 * @description 채권신고담당자 조회
 * @returns {void}
 * @hidden N
 */
scwin.search2 = function() {
    dts_List3.removeAll();
    const isur_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "ISUR_CD");
    let dsNm = 'BNS_BND_DECL_CHRG_LIST';
    let qryId = 'lds.stf.bnsdecl_mgr.select.selectBndDeclChrgList';
    let param = '&{P}V_ISUR_CD=' + isur_cd;
    $c.bns.fn_SearchBns("ULDBNS24600.xml", dts_List3, dsNm, qryId, param);
};

/**
 * @method
 * @name getParListBndIsu
 * @description 상장종목 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParListBndIsu = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: "1" // 1 : 상장종목만, 2 : 상장폐지도 포함, else : 모두
            ,
        ISUR_NM: "",
        ISU_NM: txb_IsuNm.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParListBndIsu
 * @description 상장종목 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParListBndIsu = function(arrPar) {
    txb_StdCd.setValue(arrPar[0].STD_CD);
    txb_IsuNm.setValue(arrPar[0].ISU_NM);
};

/**
 * @method
 * @name getCommonKey
 * @description 팝업에 넘길 키데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getCommonKey = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_List1.getCellData(dts_List1.getRowPosition(), "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_List1.getCellData(dts_List1.getRowPosition(), "BND_LIST_PROCS_TP_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name ksdApiCall
 * @description 예탁원 API를 Call 하여 발행등록사실확인정보를 가져온다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ksdApiCall = async function() {
    if (edt_FromDt.getValue() === "" || edt_ToDt.getValue() === "") {
        await $c.win.alert("상장일자를 입력하세요.");
        return;
    }
    if (!confirm("예탁원 발행등록사실확인정보를 요청하시겠습니까?")) return;
    let url;
    url = "/MktVerifSystem.do?method=recvKsdIsuRegFactReq";
    url += "&SCREN_ID=" + "ULDBNS24600.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 파라미터 세팅
    let param = "FROM_DT=" + edt_FromDt.getValue();
    param += ", TO_DT=" + edt_ToDt.getValue();
    param += ", ISSU_REGI_SEC_TP_CD=11"; // 채권 고정
    param += ", ISIN=" + txb_StdCd.getValue();
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_CallDt)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name setSearchDt
 * @description 조회조건 구하기.. 현재일로부터 영업일기준으로 T-1 ~ T+2 일
 * @returns {void}
 * @hidden N
 */
scwin.setSearchDt = function() {
    const base_dt = $c.ut.cGetToday2();
    const offPrev = 1;
    const offNext = 1;
    $c.bns.getBusinessDay("ULDBNS24600.xml", dts_BizDt, base_dt, offPrev, offNext);
    edt_FromDt.setValue(dts_BizDt.getCellData(1, "FROM_DT"));
    edt_ToDt.setValue(dts_BizDt.getCellData(1, "TO_DT"));
};

/**
 * @method
 * @name getKsdApiCallDt
 * @description 예탁원발행등록사실정보 api 최근 호출일 조회
 * @returns {void}
 * @hidden N
 */
scwin.getKsdApiCallDt = function() {
    let param = '';
    param += "&{P}V_CASE=ISU_REG";
    let dsNm = 'BNS_KSD_ISU_REG_CALL_DT';
    let qryId = 'lds.stf.bnsdecl_mgr.select.getMaxCallDt';
    $c.bns.fn_SearchBns("ULDBNS24600.xml", dts_CallDt, dsNm, qryId, param);
};
